from pathlib import Path
p=Path('frontend/src/CorpusLibrary.tsx');s=p.read_text(encoding='utf-8')
s=s.replace('<b>0</b><span>Mustaqil lingvistik tasdiq</span>', '<b>{dataset?.clips.filter(c=>c.verified).length||0}</b><span>Qayd etilgan ekspert tasdig‘i</span>')
s=s.replace('<div className="corpus-layout">', '<label>Tekshiruv holati<select value={reviewFilter} onChange={e=>setReviewFilter(e.target.value)}><option value="all">Barcha kliplar</option><option value="unreviewed">Tekshirilmagan</option><option value="approved">Ekspert tasdiqlagan</option><option value="needs_review">Qayta tekshirish kerak</option><option value="rejected">Rad etilgan</option></select></label><div className="corpus-layout">')
s=s.replace("{c.duration.toFixed(2)} s · {c.technical_valid?'Fayl tekshirildi':'Manba klipi'} · ASL", "{c.duration.toFixed(2)} s · {c.verified?'Ekspert tasdig‘i':c.review_decision==='rejected'?'Rad etilgan':c.technical_valid?'Fayl tekshirildi':'Manba klipi'} · ASL")
s=s.replace('</a></>:<p>Ijroni', '''</a><details><summary>Ekspert tekshiruvi va xulosasi</summary><p>Tasdiqlash — ishoraning ma’nosi, qo‘l shakli va vaqtini haqiqatan tekshirgan mutaxassis xulosasi. Import yoki fayl testi lingvistik tasdiq bermaydi.</p><label>Tekshiruvchi<input value={reviewer} onChange={e=>setReviewer(e.target.value)} placeholder="Ism-familiya va malaka"/></label><label>Xulosa<select value={decision} onChange={e=>setDecision(e.target.value)}><option value="needs_review">Qayta tekshirish kerak</option><option value="approved">Tasdiqlangan</option><option value="rejected">Rad etilgan — tarjimada ishlatilmasin</option></select></label><label>Asoslangan izoh<textarea value={notes} onChange={e=>setNotes(e.target.value)} placeholder="Ma’no, vaqt, qo‘l shakli va tekshiruv mezonlari"/></label><button disabled={saving||reviewer.trim().length<3||notes.trim().length<15} onClick={saveReview}>{saving?'Saqlanmoqda…':'Xulosani saqlash'}</button></details></>:<p>Ijroni''')
p.write_text(s,encoding='utf-8')
